# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: what a GitHub Copilot seat has used of its quotas this period (read-only): the
#          premium quota (the one that runs out), chat and completions, the plan and the day
#          they reset. The figures VS Code's Copilot status shows. Needs the stored Copilot
#          token (`ds settings sync`).
# Usage: usage = copilot_usage() -> CopilotUsage (1 GET request, logged by ds.util.http).
# ---------------------------------------------------------------------------
from __future__ import annotations

import datetime as dt
from http import HTTPStatus
from typing import TYPE_CHECKING, Any
from urllib.parse import parse_qs

from pydantic import BaseModel

from ds.ai.model import SEAT_QUOTA_HEADER
from ds.settings import get_settings
from ds.util import http

if TYPE_CHECKING:
    from collections.abc import Mapping

    import httpx2

__all__ = ["CopilotRefusedError", "CopilotUsage", "Quota", "copilot_usage", "usage_from_headers"]

# ds::external-source: checked 2026-11-20 https://api.github.com/copilot_internal/user
#   GitHub's own endpoint for its editors' Copilot status: not documented, so it can change
#   without notice. Taken from one answer (an individual_pro seat; a business seat's wasn't
#   seen, so every field is read as optional): copilot_plan, quota_reset_date
#   ("2026-12-01"), token_based_billing, and quota_snapshots.{premium_interactions, chat,
#   completions} with entitlement, quota_remaining, percent_remaining, unlimited,
#   credits_used, overage_count, overage_permitted
API_URL = "https://api.github.com/copilot_internal/user"
SOURCE = "github"
_REFUSED = (HTTPStatus.UNAUTHORIZED, HTTPStatus.FORBIDDEN, HTTPStatus.NOT_FOUND)


class CopilotRefusedError(RuntimeError):
    """No Copilot token is stored, or GitHub won't give this token the seat's usage (a wrong
    kind of token, no seat, or an organization's policy).
    """


class Quota(BaseModel):
    """One quota of the seat for the current period."""

    limit: float = 0
    """What the period allows (the API's entitlement); 0 when unlimited."""
    used: float = 0
    percent_used: float = 0
    unlimited: bool = False
    overage: float = 0
    """Used beyond the limit, where the seat allows that."""


class CopilotUsage(BaseModel):
    """A seat's plan, its quotas for the current period and the day they reset."""

    plan: str = ""
    """The seat's plan as GitHub names it, eg 'individual_pro', 'business'."""
    resets: dt.date | None = None
    unit: str = "requests"
    """What the premium quota counts: 'credits' on token based billing, else 'requests'."""
    premium: Quota | None = None
    """None when GitHub's answer has no premium quota."""
    chat: Quota | None = None
    completions: Quota | None = None


def _quota(data: dict[str, Any] | None) -> Quota | None:
    if not data:
        return None
    limit = float(data.get("entitlement") or 0)
    left = float(data.get("quota_remaining", data.get("remaining")) or 0)
    percent_left = data.get("percent_remaining")
    unlimited = bool(data.get("unlimited"))
    # what is gone from the limit, as VS Code shows it (eg 35.5): `credits_used` is the same
    # figure rounded down to whole credits, so it is only read where there is no limit
    used = max(0.0, limit - left) if limit else data.get("credits_used") or 0
    return Quota(
        limit=limit,
        used=float(used),
        percent_used=0 if unlimited or percent_left is None else max(0.0, 100 - float(percent_left)),
        unlimited=unlimited,
        overage=float(data.get("overage_count") or 0),
    )


def _date(text: str | None) -> dt.date | None:
    try:
        return dt.date.fromisoformat(text[:10]) if text else None
    except ValueError:
        return None


def _header_quota(value: str | None) -> tuple[Quota | None, dt.date | None]:
    """One `x-quota-snapshot-*` header, eg 'ent=7000&ov=0.0&ovPerm=false&rem=99.4&rst=<date>':
    ent is the limit (-1: unlimited), rem the percent left (one decimal), rst the reset time.
    """
    if not value:
        return None, None
    fields = {name: found[0] for name, found in parse_qs(value).items()}
    try:
        limit, percent_left = float(fields["ent"]), float(fields["rem"])
        overage = float(fields.get("ov") or 0)
    except (KeyError, ValueError):
        return None, None
    unlimited = limit < 0
    percent_used = 0.0 if unlimited else max(0.0, 100 - percent_left)
    quota = Quota(
        limit=0 if unlimited else limit,
        used=0 if unlimited else limit * percent_used / 100,
        percent_used=percent_used,
        unlimited=unlimited,
        overage=overage,
    )
    return quota, _date(fields.get("rst"))


def usage_from_headers(headers: Mapping[str, str]) -> CopilotUsage | None:
    """The seat's usage as a Copilot answer's own headers give it (ds.ai.model leaves them on
    the call's record): no request is sent. None when the premium quota isn't among them.

    Less than copilot_usage() gives: no plan and no unit (they keep their defaults), and
    `used` is worked out from a percent with one decimal, so it is exact only to a thousandth
    of the limit (7 of 7,000 credits).
    """
    premium, resets = _header_quota(headers.get(f"{SEAT_QUOTA_HEADER}premium_interactions"))
    if premium is None:
        return None
    return CopilotUsage(
        resets=resets,
        premium=premium,
        chat=_header_quota(headers.get(f"{SEAT_QUOTA_HEADER}chat"))[0],
        completions=_header_quota(headers.get(f"{SEAT_QUOTA_HEADER}completions"))[0],
    )


def copilot_usage(client: httpx2.Client | None = None) -> CopilotUsage:
    """The seat's usage as GitHub has it now.

    Args:
        client: an httpx2.Client to send with (tests fake the transport); else a one-off
            request.

    CopilotRefusedError when no token is stored or GitHub answers 401 / 403 / 404 (its message
    is kept; nothing is retried and no other way in is tried). Any other failure raises
    httpx2's own error.
    """
    token = get_settings().github_copilot_token
    if token is None:
        raise CopilotRefusedError("no GitHub Copilot token is stored (run `ds settings sync`)")
    headers = {"Authorization": f"Bearer {token.get_secret_value()}", "Accept": "application/json"}
    with http.request("GET", API_URL, source=SOURCE, name="copilot usage", client=client, headers=headers) as (
        resp,
        call,
    ):
        if resp.status_code in _REFUSED:
            try:
                said = resp.json().get("message", "")
            except ValueError:
                said = ""
            raise CopilotRefusedError(f"GitHub refused ({resp.status_code}{f': {said}' if said else ''})")
        resp.raise_for_status()
        data = resp.json()
        quotas = data.get("quota_snapshots") or {}
        usage = CopilotUsage(
            plan=data.get("copilot_plan") or "",
            resets=_date(data.get("quota_reset_date")),
            unit="credits" if data.get("token_based_billing") else "requests",
            premium=_quota(quotas.get("premium_interactions")),
            chat=_quota(quotas.get("chat")),
            completions=_quota(quotas.get("completions")),
        )
        call["plan"] = usage.plan
        return usage
